function showPanel(){const panels=[...$('#editor').querySelectorAll('.linear-panel')];panels.forEach((p,i)=>{p.hidden=i!==state.view.panel;if(i===state.view.panel)p.scrollTop=0;});$('#panel-position').textContent=`${state.view.panel+1} / ${panels.length}`;$('#panel-choice').value=state.view.panel;$('#previous').disabled=state.step===0&&state.view.panel===0;$('#next').disabled=state.step===6&&state.view.panel===panels.length-1;$('#next').textContent=state.view.panel===panels.length-1?'Nächster Schritt →':'Weiter →';updateDialogue(state);}
function advancePanel(direction){if(direction>0&&state.step===5){const report=dialogueReport(state),id=$('#editor .linear-panel:not([hidden])')?.dataset.questionId,question=report.questions.find(q=>q.id===id);if((question&&!question.ready)||(id==='summary'&&report.missing)){updateDialogue(state);toast('Beantworte zuerst die Leitfrage oder halte einen vollständigen Klärungsauftrag fest.');return;}if(id==='summary'){go(6);return;}}const total=$('#editor').querySelectorAll('.linear-panel').length;const next=state.view.panel+direction;if(next<0){if(state.step>0){state.step--;state.view.panel=999;render();}}else if(next>=total){if(state.step===5){const report=dialogueReport(state);if(report.missing){openPlanningQuestion(report.questions.find(q=>!q.ready).id);toast('Vor dem Abschluss fehlen noch Antworten oder vollständige Klärungsaufträge.');return;}}if(state.step<6)go(state.step+1);}else{state.view.panel=next;showPanel();save();}}
function revealField(input){const panel=input.closest('.linear-panel');if(panel){state.view.panel=[...$('#editor').querySelectorAll('.linear-panel')].indexOf(panel);showPanel();save();}}
function switchMode(mode){if(mode!==state.view.mode)state.view.previousMode=state.view.mode;if(state.view.mode==='map'&&mode!=='map')studio?.clearHistory();state.view.mode=mode;render();}
function drawMap(){const root=$('#mindmap');if(!root)return;root.innerHTML=`<div class="map-preview">${state.topic?escape(state.topic):'Dein Ausgangspunkt'}<span>↳ ${state.ideas.length} Assoziationen · ${personalSeeds(state).length} persönliche Spuren</span><button id="open-map-preview">Im freien Denkraum weiterdenken ↗</button></div>`;$('#open-map-preview').onclick=()=>switchMode('map');}
