function renderCandidates(){$('#candidates').innerHTML=state.candidates.length?`<div class="table-wrap"><table><thead><tr><th>Variante</th><th>Bewertung*</th><th>Aufwand / Zeit</th><th></th></tr></thead><tbody>${state.candidates.map((c,i)=>{const e=evaluate(c);return `<tr><td>${escape(c.title||c.topic||'Ohne Titel')}<br><small>${escape(c.question)}</small></td><td>${e.score??'–'}/100</td><td>${e.timeComplete?'':'mind. '}${e.needed.toFixed(1)}${e.neededHigh>e.needed?'–'+e.neededHigh.toFixed(1):''} / ${e.usable.toFixed(1)} h${e.timeComplete?'':' · Rest offen'}</td><td><button data-restore="${i}">Laden</button> <button data-drop="${i}" aria-label="Variante entfernen">×</button></td></tr>`;}).join('')}</tbody></table></div><p class="help">* Jede Variante nutzt ihre gespeicherten Gewichtungen. Für einen fairen Vergleich dieselben Gewichte verwenden. Vor dem Laden wird dein aktueller Entwurf automatisch als Variante gesichert.</p>`:'<p class="empty">Noch keine Varianten. Verändere eine Stellschraube und merke dir den Stand.</p>';document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.restore),chosen=state.candidates[i];const candidates=[...state.candidates];candidates[i]={...structuredClone(state),candidates:[]};state=normalize({...chosen,candidates,step:4});render();toast('Variante geladen, vorheriger Entwurf als Variante gesichert.');});document.querySelectorAll('[data-drop]').forEach(b=>b.onclick=()=>{state.candidates.splice(Number(b.dataset.drop),1);save();renderCandidates();});}
