function conceptCheckPage(){return planningSection('Konzeptprüfung · was fehlt noch?',`<details class="audit-explanation"><summary>So funktioniert die Prüfung</summary><p class="help">Die Prüfung kontrolliert Angaben und einfache Widersprüche, keine fachliche Qualität oder externe Quellen. «Selbst geprüft» bestätigt deine eigene Kontrolle anhand des Prüfauftrags. Relevante Änderungen heben die Bestätigung auf. Standardgliederungen und Pauschalzeiten sind keine ausgearbeitete Planung.</p></details><button id="export-formal-check">Prüfbericht und Konzeptangaben exportieren ↓</button><div id="concept-check-results"></div>`)+formalGroups.filter(([g])=>g!=='Betreuung und Entscheidungen').flatMap(([g,fields])=>{const parts=[];for(let i=0;i<fields.length;i+=2)parts.push(planningSection(g+' · '+(i/2+1),fields.slice(i,i+2).map(([k,l])=>field(l,'formal.'+k,k==='standardsSource'?'Dokument / Link, Version, Abschnitt und Datum deiner Prüfung.':'So konkret, dass die Angabe überprüft werden kann. Falls nicht zutreffend: mit Bezug zur Vorgabe begründen.',true)).join(''),g==='Verbindliche Formvorgaben'?'Schulvorgaben haben Vorrang. Hier werden keine universellen Seitenzahlen oder Zitiernormen vorgegeben.':''));return parts;}).join('');}
function updateConceptCheck(){const audit=conceptAudit(state);const calendar=$('#calendar-check');if(calendar)calendar.innerHTML=audit.issues.length?`<ul class="audit-issues">${audit.issues.map(i=>`<li>${escape(i)}</li>`).join('')}</ul>`:'<p class="help">Noch keine datumsbezogenen Widersprüche erkannt. Fehlende Termine im Konzeptcheck ergänzen.</p>';const root=$('#concept-check-results');if(!root)return;const filtered=audit.rows.filter(r=>auditFilter==='all'||r.status===auditFilter);auditPage=Math.max(0,Math.min(auditPage,Math.ceil(filtered.length/8)-1));root.innerHTML=`<p class="audit-summary"><strong>${audit.missing} fehlen</strong> · ${audit.entered} vorhanden, ungeprüft · ${audit.reviewed} selbst geprüft</p>${audit.issues.length?`<details><summary>Widersprüche / Klärungsbedarf (${audit.issues.length})</summary><ul>${audit.issues.map(i=>`<li>${escape(i)}</li>`).join('')}</ul></details>`:''}<div class="audit-controls"><label>Prüfpunkte anzeigen<select id="audit-filter" aria-label="Prüfpunkte filtern">${[['all','Alle'],['missing','Fehlende Angaben'],['entered','Vorhanden, ungeprüft'],['reviewed','Selbst geprüft']].map(([id,label])=>`<option value="${id}" ${auditFilter===id?'selected':''}>${label}</option>`).join('')}</select></label><button id="audit-prev" ${auditPage===0?'disabled':''}>←</button><span>${filtered.length?auditPage*8+1:0}–${Math.min(filtered.length,(auditPage+1)*8)} / ${filtered.length}</span><button id="audit-next" ${(auditPage+1)*8>=filtered.length?'disabled':''}>→</button></div><div class="audit-list">${filtered.slice(auditPage*8,(auditPage+1)*8).map(r=>`<details class="audit-row ${r.status}"><summary><span>${r.status==='missing'?'○ Fehlt':r.status==='reviewed'?'✓ Selbst geprüft':'◐ Vorhanden'}</span> ${escape(r.title)}</summary><p>${escape(r.hint)}</p><button data-audit-edit="${r.id}">Angabe bearbeiten →</button>${r.status!=='missing'?`<button data-audit-review="${r.id}">${r.status==='reviewed'?'Prüfbestätigung zurücknehmen':'Anhand dieses Prüfauftrags selbst geprüft'}</button>`:''}</details>`).join('')}</div>`;root.querySelector('#audit-filter').onchange=e=>{auditFilter=e.target.value;auditPage=0;updateConceptCheck();};root.querySelector('#audit-prev').onclick=()=>{auditPage--;updateConceptCheck();};root.querySelector('#audit-next').onclick=()=>{auditPage++;updateConceptCheck();};root.querySelectorAll('[data-audit-edit]').forEach(b=>b.onclick=()=>{const row=audit.rows.find(r=>r.id===b.dataset.auditEdit);go(row.step);const input=document.querySelector('[data-path="'+row.path+'"]');if(input){revealField(input);input.focus();}});root.querySelectorAll('[data-audit-review]').forEach(b=>b.onclick=()=>{const row=conceptAudit(state).rows.find(r=>r.id===b.dataset.auditReview);if(row.status==='reviewed')delete state.formal.reviews[row.id];else state.formal.reviews[row.id]=row.signature;save();updateConceptCheck();if($('#concept-preview'))$('#concept-preview').textContent=concept(state);});$('#export-formal-check').onclick=()=>exportsUI.open('Konzeptprüfung · Formalien und Vollständigkeit',formalExport(state));}
